import sys, subprocess, os, itertools

xsl = ('<xsl:stylesheet version="1.0" xmlns:xsl="http://www.w3.org/1999/XSL/Transform">\n'
       '<xsl:import href="zzz"/>\n'
       '<xsl:template match="/">ok</xsl:template>\n'
       '</xsl:stylesheet>')

def ent(u,c): return u.encode()+b'\\\n'+(c if isinstance(c,bytes) else c.encode())+b'\\\n'

def mk_dtd(style):
    parts=[]
    if style=='A':
        parts.append('<!ATTLIST e '+ " ".join(f'a{i} CDATA "v"' for i in range(14))+'>')
    elif style=='B':
        for e in range(12):
            parts.append(f'<!ATTLIST c{e} '+ " ".join(f'b{i} CDATA "w"' for i in range(4))+'>')
        parts.append('<!ATTLIST e '+ " ".join(f'a{i} CDATA "v"' for i in range(14))+'>')
    elif style=='C':
        for e in range(40):
            parts.append(f'<!ATTLIST x{e} '+ " ".join(f'b{i} CDATA "w"' for i in range(2))+'>')
        parts.append('<!ATTLIST e '+ " ".join(f'a{i} CDATA "v"' for i in range(14))+'>')
    elif style=='D':
        reps=5
        for r in range(reps):
            parts.append(f'<!ATTLIST e '+ " ".join(f'a{r}_{i} CDATA "v"' for i in range(3))+'>')
    elif style=='E':
        parts.append('<!ATTLIST p:e '+ " ".join(f'a{i} CDATA "v"' for i in range(14))+'>')
    elif style=='F':
        parts.append('<!ATTLIST e '+ " ".join(f'a{i} CDATA "v{i}"' for i in range(30))+'>')
    elif style=='G':
        # grow element 'e' root matches so defaults are applied
        pass
    return ("<!DOCTYPE r [\n"+"\n".join(parts)+"\n]>\n<r/>").encode()

def run(style, start, end, wid):
    imp=mk_dtd(style)
    for n in range(start, end):
        data = n.to_bytes(4,'big')
        data += ent('main.xsl', xsl) + ent('doc.xml','<doc/>') + ent('zzz', imp)
        data += b'Z'*9000
        open(f'/tmp/cmp{wid}.bin','wb').write(data)
        r=subprocess.run(['./xslt_arvo',f'/tmp/cmp{wid}.bin'], capture_output=True, env={**os.environ,'ASAN_OPTIONS':'detect_leaks=0'})
        out=r.stderr.decode('latin1','ignore')
        if 'double-free' in out or 'attempting free' in out or ('use-after' in out) or 'heap-buffer' in out:
            print(f"HIT style={style} n={n}")
            for line in out.splitlines():
                if 'ERROR:' in line or 'located' in line or 'DefAttrs' in line or 'HashFree' in line or 'SCAR' in line:
                    print("   "+line)
            return
    print(f"worker {wid} style {style} range {start}-{end} done")

if __name__=='__main__':
    run(sys.argv[1], int(sys.argv[2]), int(sys.argv[3]), sys.argv[4])
EOF
for w in 0 1 2 3 4 5 6 7; do
  case $w in
    0) s=A;; 1) s=B;; 2) s=C;; 3) s=D;; 4) s=E;; 5) s=F;; 6) s=B;; 7) s=C;;
  esac
  st=$((1 + w*1200)); en=$((st+1199)); if [ $w -ge 6 ]; then st=$((2401 + (w-6)*1200)); en=$((st+1199)); fi
  python3 campaign2.py $s $st $en $w > /tmp/camp_$w.log 2>&1 &
done
wait
echo "=== results ==="; cat /tmp/camp_*.log

